#include <array>
#include <cstdint>

std::uint32_t swapBytes(std::uint32_t value)
{
    return ((value & 0x000000FFu) << 24) | ((value & 0x0000FF00u) << 8) | ((value & 0x00FF0000u) >> 8) | ((value & 0xFF000000u) >> 24);
}

std::array<std::uint8_t, 4> toBigEndian(std::uint32_t value)
{
    return { static_cast<std::uint8_t>(value >> 24), static_cast<std::uint8_t>(value >> 16), static_cast<std::uint8_t>(value >> 8), static_cast<std::uint8_t>(value) };
}

std::uint32_t fromBigEndian(const std::array<std::uint8_t, 4>& bytes)
{
    return (static_cast<std::uint32_t>(bytes[0]) << 24) | (static_cast<std::uint32_t>(bytes[1]) << 16) | (static_cast<std::uint32_t>(bytes[2]) << 8) | static_cast<std::uint32_t>(bytes[3]);
}

unitTests:
TEST("swapBytes") { CHECK_EQ(swapBytes(0x12345678u), 0x78563412u); CHECK_EQ(swapBytes(0x000000FFu), 0xFF000000u); CHECK_EQ(swapBytes(swapBytes(0xCAFEBABEu)), 0xCAFEBABEu); }
TEST("toBigEndian") { const auto b{ toBigEndian(0x12345678u) }; CHECK_EQ(b[0], 0x12); CHECK_EQ(b[1], 0x34); CHECK_EQ(b[2], 0x56); CHECK_EQ(b[3], 0x78); }
TEST("round trip") { for (std::uint32_t v : { 0u, 1u, 0xDEADBEEFu, 0xFFFFFFFFu, 0x00FF00FFu }) CHECK_EQ(fromBigEndian(toBigEndian(v)), v); }

